mapper.select:
SELECT a.id id, a.contract_id contract_id, a.receipt_id receipt_id, b.contract_code contract_code, b.proj_name proj_name, b.proj_classify proj_classify, b.proj_source proj_source, b.contract_start_date contract_start_date, b.profit_belong_dept_id belong_dept_id, c.proj_sponsor_user_id sponsor_user_id, a.profit_current profit_current, a.profit_total profit_total, a.profit_adjust profit_adjust, a.bonus_current bonus_current, a.bonus_total bonus_total, a.calculate_date_year calculate_date_year, a.calculate_date_month calculate_date_month, a.payment_current payment_current, a.payment_total payment_total FROM kpi_proj_guess_base_info a, kpi_project_distribution_base_info_lib b, contract_base_info c
a.kpi_project_distribution_id = b.project_distribution_id and a.contract_id = c.id and a.kpi_project_distribution_version = b.version and b.contract_code like CONCAT('%',#{param.contractCode},'%') and b.proj_name like CONCAT('%',#{param.projName},'%') and b.profit_belong_dept_id = #{param.deptId} and c.proj_sponsor_user_id = #{param.userId} and c.proj_sponsor_user_id = #{param.sponsorUserId} and a.calculate_date_year = #{param.calculateDateYear} and a.calculate_date_month = #{param.calculateDateMonth}
order by a.calculate_date_year desc, a.calculate_date_month desc, a.contract_id desc

SELECT a.id id, a.contract_id as contract_id, a.receipt_id as receipt_id, a.award_ratio award_ratio, a.kpi_project_distribution_id project_distribution_id, a.kpi_project_distribution_id kpi_project_distribution_id, a.kpi_project_distribution_version version, b.contract_code contract_code, b.proj_name proj_name, b.proj_classify proj_classify, b.proj_source proj_source, b.contract_start_date contract_start_date, b.profit_belong_dept_id belong_dept_id, c.proj_sponsor_user_id sponsor_user_id, a.profit_current profit_current, a.profit_total profit_total, a.bonus_current bonus_current, a.bonus_total bonus_total, a.payment_current payment_current, a.payment_total payment_total, a.calculate_date_year calculate_date_year, a.calculate_date_month calculate_date_month, c.biz_type, c.lease_type, c.factoring_type, c.zr_type, a.proj_payment_year_amount, a.contract_payment_month_amount FROM kpi_proj_guess_base_info a, kpi_project_distribution_base_info_lib b, contract_base_info c
a.kpi_project_distribution_id = b.project_distribution_id and a.contract_id = c.id and a.kpi_project_distribution_version = b.version and a.contract_id = #{param.contractId} and a.calculate_date_year = #{param.calculateDateYear} and a.calculate_date_month = #{param.calculateDateMonth} and c.proj_sponsor_user_id = #{param.sponsorUserId} and b.profit_belong_dept_id = #{param.deptId}
order by a.calculate_date_year desc, a.calculate_date_month desc, a.contract_id desc

SELECT a.dept_id,
a.divide_type,
a.divide_target as divide_target_id,
sum(a.bonus_current) as bonus_current,
sum(a.payment_current) as payment_current
FROM kpi_proj_guess_divide a
where a.divide_type = #{param.divideType}
and a.divide_year = #{param.calculateDateYear} and a.divide_month = #{param.calculateDateMonth}

    and a.dept_id = #{param.deptId}


    and a.divide_type = #{param.divideType}


    and a.divide_target = #{param.divideTargetId}


  and a.divide_type != 'BUSINESS_DEPT'
  and a.divide_target = #{param.sponsorUserId}

group by a.dept_id, a.divide_type, a.divide_target
order by a.dept_id desc, a.divide_type desc, a.divide_target desc

select a.dept_id, a.divide_type, a.divide_target divide_target_id, a.bonus_current as bonus_current, a.payment_current as payment_current from (SELECT a.dept_id, a.divide_type, a.divide_target, sum(a.bonus_current) as bonus_current, sum(a.payment_current) as payment_current FROM kpi_proj_guess_divide a where a.divide_type = #{param.divideType} and a.divide_year = #{param.calculateDateYear} and a.divide_month = #{param.calculateDateMonth} group by a.dept_id, a.divide_type, a.divide_target) a
and a.dept_id = #{param.deptId}
and a.divide_type = #{param.divideType}
and a.divide_target = #{param.divideTargetId}
and a.divide_type != 'BUSINESS_DEPT' and a.divide_target = #{param.sponsorUserId}
order by a.dept_id desc, a.divide_type desc, a.divide_target desc

SELECT
       a.dept_id deptId,
    a.kpi_proj_guess_id,
       a.divide_type,
       a.divide_target,
    sum(a.bonus_current)   as bonus_current,
    sum(a.payment_current) as payment_current
FROM kpi_proj_guess_divide a inner join kpi_proj_guess_base_info b on a.kpi_proj_guess_id = b.id

    
        and a.divide_year = #{param.calculateDateYear}
    
    
        and a.divide_month = #{param.calculateDateMonth}
    
    
        and b.proj_classify = #{param.projClassify}
    
    
        and b.proj_source = #{param.projSource}
    
    
        and a.divide_type = #{param.divideType}
    
    
        and a.dept_id = #{param.deptId}
    
    
        and a.divide_type != 'BUSINESS_DEPT'
        and a.divide_target = #{param.sponsorUserId}
    

group by a.dept_id, a.divide_type, a.divide_target

SELECT a.divide_year divide_year, a.divide_month divide_month, sum(a.profit_total) as profit_total, sum(a.bonus_total) as bonus_total, sum(a.payment_total) as payment_total, sum(a.payment_total) as payment_total_amount, sum(a.bonus_total) + sum(a.payment_total) as amount FROM kpi_proj_guess_divide a where a.divide_type = 'BUSINESS_DEPT'
and a.divide_type != 'BUSINESS_DEPT' and a.divide_target = #{param.sponsorUserId}
group by a.divide_year, a.divide_month order by a.divide_year desc, a.divide_month desc
